# Generated by scripts/render-formula.mjs from packaging/homebrew/devbridge-agent.rb.tmpl
# in https://github.com/adityaraja338/devbridge. Edit the template, not this file.
class DevbridgeAgent < Formula
  desc "Mac agent that lets a Windows PC build and run apps on the iOS Simulator"
  homepage "https://github.com/adityaraja338/devbridge"
  url "https://github.com/adityaraja338/devbridge/releases/download/v0.6.1/devbridge-0.6.1.tgz"
  sha256 "c38fedcb30235837fa1939467887b8562a657be14431980152ca4d1b81d1d135"
  license "MIT"
  # Version 0.6.1: brew parses it from the url's devbridge-X.Y.Z.tgz file name,
  # so there is no `version` line (brew audit calls one redundant).

  depends_on :macos
  depends_on "cocoapods"
  depends_on "node"
  # idb_companion (facebook/fb/idb-companion) is deliberately not a dependency: a
  # broken third-party tap would break `brew install`. `devbridge-agent setup`
  # installs it, and `devbridge-agent doctor` only warns when it's missing.

  def install
    # std_npm_args packs the source and runs `npm install --global --prefix=libexec`,
    # so the package lands in libexec/lib/node_modules/devbridge and npm links its
    # bins into libexec/bin. Only the agent bin goes on the user's PATH; the
    # Windows-side `devbridge` CLI stays inside libexec. A wrapper rather than a
    # symlink, so the command runs on brew's node even when nvm or volta put an
    # older node first on PATH (the bin's shebang is `env node`).
    system "npm", "install", *std_npm_args
    (bin/"devbridge-agent").write_env_script libexec/"bin/devbridge-agent", PATH: "#{Formula["node"].opt_bin}:$PATH"
  end

  def caveats
    <<~EOS
      Finish setting up the Mac (Xcode, simulator runtime, idb_companion):
        devbridge-agent setup
      Then start the agent, now and at every login:
        brew services start devbridge-agent
      And pair your PC:
        devbridge-agent pair

      Never run `brew services` with sudo: the agent must run as you, in your
      login session, to reach the Simulator.
      Logs: ~/Library/Logs/devbridge-agent.log
    EOS
  end

  service do
    # Node by its full path, so the service doesn't depend on the PATH launchd gives it.
    run [Formula["node"].opt_bin/"node", opt_libexec/"lib/node_modules/devbridge/bin/devbridge-agent.js", "serve"]
    # Restart on crashes; a clean exit (e.g. another agent already running) stays down.
    keep_alive successful_exit: false
    # Interactive: the agent drives Xcode and the Simulator, so launchd shouldn't throttle it.
    process_type :interactive
    environment_variables PATH: std_service_path_env, LANG: "en_US.UTF-8", LC_ALL: "en_US.UTF-8"
    # Dir.home is evaluated when `brew services start` writes the plist, i.e. as the
    # user running it (another reason not to use sudo).
    log_path "#{Dir.home}/Library/Logs/devbridge-agent.log"
    error_log_path "#{Dir.home}/Library/Logs/devbridge-agent.log"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/devbridge-agent --version")
  end
end
